------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- List current monitors and supported resolutions with: hyprctl monitors all

-- Toolkit-specific scale (matches the 2x XWayland/monitor scale below).
hl.env("GDK_SCALE", "2")
hl.env("XCURSOR_SIZE", "32")
hl.env("XCURSOR_THEME", "macOS")
hl.env("STEAM_FORCE_DESKTOPUI_SCALING", "1")

hl.config({
	xwayland = {
		force_zero_scaling = true,
	},
})

local internalMonitor = "eDP-1"
local internalMonitorSettings = { output = internalMonitor, mode = "2944x1840@90.00Hz", position = "0x0", scale = 2 }

hl.monitor(internalMonitorSettings)

hl.monitor({ output = "DP-8", mode = "1920x1080", position = "1920x0", scale = 1 })
hl.monitor({ output = "DP-9", mode = "1920x1080", position = "0x0", scale = 1 })

------------------------
---- HYPRSPLIT ----------
------------------------

-- Independent per-monitor workspaces (dwm/awesome-style), replacing Hyprland's
-- default global workspace numbering. See https://github.com/shezdy/hyprsplit
local hs = require("hyprsplit")

hs.config({ num_workspaces = 5, persistent_workspaces = true })

-- Pin ranges to physical outputs rather than connector enumeration order, so
-- the split stays stable across dock/undock and lid-close/open (which add and
-- remove eDP-1 at runtime, see below): eDP-1 -> 1-5, DP-8 -> 6-10, DP-9 -> 11-15.
hs.monitor_priority({ internalMonitor, "DP-8", "DP-9" })

----------------------------------
---- LID SWITCH / DOCK BEHAVIOR ----
----------------------------------

-- Goal: lid closed while docked (external monitors present) -> internal
-- panel off, externals stay on. Lid open, or undocked -> internal panel
-- on. logind handles the "lid closed and undocked" case by suspending
-- (see system/logind.nix), so it isn't handled here.

local function hasExternalMonitor()
	for _, mon in ipairs(hl.get_monitors()) do
		if mon.name ~= internalMonitor then
			return true
		end
	end
	return false
end

-- switch:on fires when the lid closes, switch:off when it opens.
hl.bind("switch:on:Lid Switch", function()
	if hasExternalMonitor() then
		hl.monitor({ output = internalMonitor, disabled = true })
	end
end, { locked = true })

hl.bind("switch:off:Lid Switch", function()
	hl.monitor(internalMonitorSettings)
end, { locked = true })

-- Safety net: if the dock is unplugged while the lid is still closed
-- (internal panel disabled), turn the internal panel back on rather than
-- leaving the system with no active output.
hl.on("monitor.removed", function(mon)
	if mon.name ~= internalMonitor and not hasExternalMonitor() then
		hl.monitor(internalMonitorSettings)
	end
end)

